import { useEffect, useState, useSyncExternalStore } from 'react';
import { allOff, anyOn, onSoundChange, setVolume, soundSupported, toggleLayer, type Layer } from '../lib/sound';
import { useStore } from '../lib/store';
import { IconNote8, IconRain, IconTree, IconWaves } from './Icons';
import { buzz, HAPTIC, Sheet } from './ui';

// Background sound: a button that shows whether anything is playing, and a
// sheet with four switches. Everything heard is generated by the app.

let sheetOpen = false;
const listeners = new Set<() => void>();
const setOpen = (v: boolean) => { sheetOpen = v; listeners.forEach((l) => l()); };
export const openSound = () => setOpen(true);

const TILES: { id: Layer; label: string; icon: typeof IconRain }[] = [
  { id: 'music', label: 'Music', icon: IconNote8 },
  { id: 'rain', label: 'Rain', icon: IconRain },
  { id: 'forest', label: 'Forest', icon: IconTree },
  { id: 'waves', label: 'Waves', icon: IconWaves },
];

// Their recordings cannot be built into the app, so these open a search in the person's own music app.
const ARTISTS = ['New Creation Worship', 'Hillsong Worship', 'Stream of Praise'];
const spotify = (a: string) => `https://open.spotify.com/search/${encodeURIComponent(a + ' instrumental')}`;
const youtube = (a: string) => `https://www.youtube.com/results?search_query=${encodeURIComponent(a + ' instrumental worship')}`;

export function SoundButton({ plain }: { plain?: boolean }) {
  const [, tick] = useState(0);
  useEffect(() => onSoundChange(() => tick((n) => n + 1)), []);
  const sound = useStore((s) => s.sound);
  const on = sound.music || sound.rain || sound.forest || sound.waves;
  if (!soundSupported()) return null;
  return (
    <button className={(plain ? 'icon-btn' : 'sound-btn') + (on ? ' on' : '')} aria-label={on ? 'Sound is on. Change sound' : 'Background sound'} aria-pressed={on} onClick={openSound} data-nogesture>
      <IconNote8 size={plain ? 22 : 18} />
      {on && <i className="sound-bars" aria-hidden><b /><b /><b /></i>}
    </button>
  );
}

export function SoundHost() {
  const open = useSyncExternalStore((l) => { listeners.add(l); return () => { listeners.delete(l); }; }, () => sheetOpen);
  const sound = useStore((s) => s.sound);
  return (
    <Sheet open={open} onClose={() => setOpen(false)} title="Sound">
      <div className="sound-grid">
        {TILES.map((t) => {
          const Icon = t.icon;
          const on = sound[t.id];
          return (
            <button key={t.id} className={'sound-tile' + (on ? ' on' : '')} aria-pressed={on} onClick={() => { buzz(HAPTIC.tap); toggleLayer(t.id); }}>
              <Icon size={30} /><span>{t.label}</span>
            </button>
          );
        })}
      </div>
      <label className="sound-volume">
        <span>Volume</span>
        <input type="range" min={0} max={1} step={0.02} value={sound.volume} onChange={(e) => setVolume(Number(e.target.value))} aria-label="Volume" />
      </label>
      {anyOn() && <button className="btn ghost small" onClick={allOff}>Turn everything off</button>}
      <p className="hint">These sounds are made by the app, so they work offline. Mix any of them.</p>

      <p className="label">Worship music in your own app</p>
      <ul className="artist-list">
        {ARTISTS.map((a) => (
          <li key={a}>
            <span>{a}</span>
            <a href={spotify(a)} target="_blank" rel="noopener noreferrer">Spotify</a>
            <a href={youtube(a)} target="_blank" rel="noopener noreferrer">YouTube</a>
          </li>
        ))}
      </ul>
      <p className="hint">Their recordings belong to them, so they play from your music app, not from Chestnut.</p>
    </Sheet>
  );
}
